body.query:
query InstallationDatasets($installation: ID!, $limit: Int!, $offset: Int!) {
  installation(key: $installation) {
    dataset(limit: $limit, offset: $offset) {
      limit
      offset
      count
      endOfRecords
      results {
        ...DatasetResult
      }
    }
  }
}

fragment DatasetResult on Dataset {
  key
  title
  excerpt
  type
  publishingOrganizationTitle
}
